const crypto = require('crypto');

const item = $input.first();
const request = (item && item.json) || {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};

function getHeader(name) {
  const target = String(name).toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      if (Array.isArray(value)) return typeof value[0] === 'string' ? value[0].trim() : '';
      return typeof value === 'string' ? value.trim() : '';
    }
  }
  return '';
}

function reject(code, message, statusCode = 401) {
  return [{ json: { authenticated: false, statusCode, code, error: message } }];
}

const rawSecret = String(($env && $env.DX_WEBHOOK_SECRET) || '').trim();
if (!rawSecret) return reject('WEBHOOK_SECRET_NOT_CONFIGURED', 'DX_WEBHOOK_SECRET is not configured.');

const secretBytes = rawSecret.startsWith('whsec_')
  ? Buffer.from(rawSecret.slice(6), 'base64')
  : Buffer.from(rawSecret, 'utf8');
if (!secretBytes || !secretBytes.length) return reject('WEBHOOK_SECRET_INVALID', 'DX_WEBHOOK_SECRET is invalid.');

const webhookId = getHeader('webhook-id');
const webhookTimestamp = getHeader('webhook-timestamp');
const webhookSignature = getHeader('webhook-signature');
if (!webhookId || !webhookTimestamp || !webhookSignature) {
  return reject('WEBHOOK_HEADERS_MISSING', 'Missing webhook-id, webhook-timestamp, or webhook-signature header.');
}
if (!/^\d{1,12}$/.test(webhookTimestamp)) {
  return reject('WEBHOOK_TIMESTAMP_INVALID', 'Invalid webhook-timestamp header.');
}
const tsSec = Number(webhookTimestamp);
const nowSec = Math.floor(Date.now() / 1000);
if (!Number.isSafeInteger(tsSec) || tsSec <= 0 || Math.abs(nowSec - tsSec) > 300) {
  return reject('WEBHOOK_TIMESTAMP_EXPIRED', 'Webhook timestamp is outside the 300s replay window.');
}

let rawBody = '';
const binaryEntry = item && item.binary && item.binary.data;
const hasInlineBinary = Boolean(binaryEntry && typeof binaryEntry.data === 'string' && binaryEntry.data.length > 0 && !binaryEntry.id);
if (typeof request.rawBody === 'string') rawBody = request.rawBody;
else if (Buffer.isBuffer(request.rawBody)) rawBody = request.rawBody.toString('utf8');
else if (hasInlineBinary) rawBody = Buffer.from(binaryEntry.data, 'base64').toString('utf8');
else if (typeof request.body === 'string') rawBody = request.body;
else if (request.body !== undefined) rawBody = JSON.stringify(request.body);

const expectedSig = crypto.createHmac('sha256', secretBytes).update(`${webhookId}.${webhookTimestamp}.${rawBody}`, 'utf8').digest('base64');
const expectedBuf = Buffer.from(expectedSig, 'utf8');
let matched = false;
for (const token of webhookSignature.split(/\s+/).filter(Boolean)) {
  if (!token.startsWith('v1,')) continue;
  const cand = Buffer.from(token.slice(3), 'utf8');
  if (cand.length === expectedBuf.length && crypto.timingSafeEqual(cand, expectedBuf)) matched = true;
}
if (!matched) return reject('WEBHOOK_SIGNATURE_INVALID', 'Standard Webhooks v1 HMAC-SHA256 verification failed.');

let parsedBody = request.body;
if (typeof parsedBody === 'string') {
  try { parsedBody = JSON.parse(parsedBody); } catch { return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be valid JSON.', 400); }
} else if (parsedBody === undefined && rawBody) {
  try { parsedBody = JSON.parse(rawBody); } catch { return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be valid JSON.', 400); }
}
if (!parsedBody || typeof parsedBody !== 'object' || Array.isArray(parsedBody)) {
  return reject('WEBHOOK_BODY_INVALID', 'Webhook payload must be a JSON object.', 400);
}
return [{ json: { authenticated: true, webhookId, webhookTimestamp: tsSec, body: parsedBody } }];

const crypto = require('crypto');

const inp = $input.first().json || {};
const body = inp.body && typeof inp.body === 'object' && !Array.isArray(inp.body) ? inp.body : {};
const data = body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : {};
const organizationId = String(data.organizationId || body.organizationId || body.organizationid || '').trim();

if (!organizationId) {
  return [{ json: { invalidPayload: true, statusCode: 400, error: 'ORGANIZATION_ID_REQUIRED', tier: 'invalid', riskScore: 0, complianceFlags: [] } }];
}

const eventType = String(body.type || body.eventType || 'compliance.evaluation').trim();
const code = String(data.code || body.code || body.subject || 'COMP-01').trim();
const rawAmount = Number(data.amount ?? body.amount ?? 0);
const amount = Number.isFinite(rawAmount) ? rawAmount : 0;
const rawSla = Number(data.slaOverdueMinutes ?? body.slaOverdueMinutes ?? 0);
const slaOverdueMinutes = Number.isFinite(rawSla) ? rawSla : 0;
const severity = String(data.severity || body.severity || 'normal').trim().toLowerCase();
const items = Array.isArray(data.items) ? data.items : (Array.isArray(body.items) ? body.items : []);
const rawTemp = data.temperatureC ?? body.temperatureC;
const temperatureC = rawTemp !== undefined && rawTemp !== null && rawTemp !== '' && Number.isFinite(Number(rawTemp)) ? Number(rawTemp) : null;

let riskScore = 10;
const flags = [];
if (amount >= 50000000) { riskScore += 35; flags.push('HIGH_VALUE_THRESHOLD'); }
else if (amount >= 15000000) { riskScore += 18; flags.push('MID_VALUE_REVIEW'); }
if (severity === 'critical') { riskScore += 30; flags.push('CRITICAL_SEVERITY'); }
else if (severity === 'high' || severity === 'urgent') { riskScore += 20; flags.push('HIGH_SEVERITY'); }
if (slaOverdueMinutes >= 30) { riskScore += 20; flags.push('SLA_CRITICAL_OVERDUE'); }
else if (slaOverdueMinutes > 0) { riskScore += 10; flags.push('SLA_WARNING'); }
if (temperatureC !== null && temperatureC > -12) { riskScore += 20; flags.push('THERMAL_EXCURSION'); }
if (items.length >= 2) { riskScore += 10; flags.push('MULTI_LINE_BATCH'); }
riskScore = Math.min(100, riskScore);

const tier = riskScore >= 75 ? 'critical' : (riskScore >= 40 ? 'escalated' : 'standard');
const idempotencyKey = crypto.createHash('sha256').update(`${organizationId}|${eventType}|${code}|${amount}|${items.length}`).digest('hex').slice(0, 24);

const allowedCollections = new Set(['latticeRequests', 'latticeOrders', 'latticeServiceTickets', 'latticeAssets', 'latticeParaDocuments', 'latticeIncidentCases']);
const rawCol = String(data.targetCollection || body.targetCollection || 'latticeRequests').trim();
const targetCollection = allowedCollections.has(rawCol) ? rawCol : 'latticeRequests';
const rawRecId = Number(data.targetRecordId ?? body.targetRecordId ?? data.id ?? body.id ?? 1);
const targetRecordId = Number.isInteger(rawRecId) && rawRecId > 0 ? rawRecId : 1;

return [{
  json: {
    invalidPayload: false,
    statusCode: 200,
    organizationId,
    eventType,
    code,
    amount,
    severity,
    slaOverdueMinutes,
    temperatureC,
    itemsProcessed: items.length,
    items,
    riskScore,
    tier,
    complianceFlags: flags,
    idempotencyKey,
    signDocumentPayload: {
      organizationId,
      targetCollection,
      targetRecordId,
      reason: `n8n compliance ${tier} (${riskScore}/100) doc=${code} key=${idempotencyKey}`.slice(0, 255),
    },
    escalationPayload: {
      organizationId,
      ruleKey: 'auto_sla_breach_escalation',
      source: 'n8n:enterprise-compliance-orchestrator',
      data: {
        code,
        tier,
        riskScore,
        complianceFlags: flags,
        priority: severity === 'critical' ? 'high' : 'high',
        severity,
      },
    },
  },
}];

const raw = $input.first().json || {};
const payload = (raw.body && raw.body.data && typeof raw.body.data === 'object') ? raw.body.data : (raw.body && typeof raw.body === 'object' ? raw.body : raw);
const signed = Boolean(payload && (payload.signed || payload.merkleRoot || (payload.entry && payload.entry.merkleRoot)));
return [{
  json: {
    kind: 'pki',
    signed,
    keyId: payload.keyId || (payload.entry && payload.entry.keyId) || null,
    merkleRoot: payload.merkleRoot || (payload.entry && payload.entry.merkleRoot) || null,
    entryHash: (payload.entry && payload.entry.entryHash) || payload.entryHash || null,
    error: signed ? null : String((raw.error && raw.error.message) || raw.message || payload.message || 'LEDGER_SIGN_UNAVAILABLE'),
  },
}];

const crypto = require('crypto');
const s = $input.first().json || {};
const lineTotal = Array.isArray(s.items) ? s.items.reduce((acc, it) => acc + (Number(it && (it.value ?? it.qty)) || 0), 0) : 0;
const manifestDigest = crypto.createHash('sha256').update(JSON.stringify({ key: s.idempotencyKey, flags: s.complianceFlags || [], items: s.items || [] })).digest('hex').slice(0, 16);
return [{
  json: {
    kind: 'partner_dossier',
    manifestDigest,
    itemCount: Array.isArray(s.items) ? s.items.length : 0,
    lineTotal,
    dispatchedChannels: ['regulatory-audit-log', 'partner-gateway-queue'],
    slaResponseDeadline: new Date(Date.now() + 2 * 3600 * 1000).toISOString(),
  },
}];

const score = $('Score Risk & Batch Compliance').first().json || {};
if (score.invalidPayload) {
  return [{ json: { ok: false, workflow: 'enterprise-compliance-orchestrator', statusCode: score.statusCode || 400, error: score.error || 'INVALID_PAYLOAD' } }];
}
const allItems = $input.all().map((it) => it.json || {});
const pki = allItems.find((x) => x.kind === 'pki') || null;
const dossier = allItems.find((x) => x.kind === 'partner_dossier') || null;
let escalationResult = null;
if (score.tier === 'escalated') {
  const escRaw = allItems[0] || {};
  const escPayload = (escRaw.body && escRaw.body.data && typeof escRaw.body.data === 'object') ? escRaw.body.data : (escRaw.body && typeof escRaw.body === 'object' ? escRaw.body : escRaw);
  const runObj = (escPayload && escPayload.run) || escPayload || {};
  escalationResult = {
    dispatched: !escRaw.error,
    runUid: runObj.runUid || null,
    status: runObj.status || (escRaw.error ? 'failed' : 'triggered'),
    error: escRaw.error ? String(escRaw.error.message || escRaw.message || 'ESCALATION_FAILED') : null,
  };
}
let execId = 'local';
try { execId = String($execution.id || 'local'); } catch {}
return [{
  json: {
    ok: true,
    statusCode: 200,
    workflow: 'enterprise-compliance-orchestrator',
    n8nExecutionId: execId,
    idempotencyKey: score.idempotencyKey,
    organizationId: score.organizationId,
    eventType: score.eventType,
    code: score.code,
    tier: score.tier,
    riskScore: score.riskScore,
    complianceFlags: score.complianceFlags || [],
    itemsProcessed: score.itemsProcessed || 0,
    pkiAttestation: pki ? { signed: Boolean(pki.signed), keyId: pki.keyId || null, merkleRoot: pki.merkleRoot || null, entryHash: pki.entryHash || null, error: pki.error || null } : null,
    partnerDispatch: dossier ? { manifestDigest: dossier.manifestDigest, itemCount: dossier.itemCount, lineTotal: dossier.lineTotal, dispatchedChannels: dossier.dispatchedChannels, slaResponseDeadline: dossier.slaResponseDeadline } : null,
    escalationResult,
    orchestratedAt: new Date().toISOString(),
  },
}];
